                sh[4] * (SH_C2_1 * yz) +
                sh[5] * (SH_C2_2 * (half(2.0) * zz - xx - yy)) +
                sh[6] * (SH_C2_3 * xz) +
                sh[7] * (SH_C2_4 * (xx - yy))
