            const Part1By2 = (x) => {
                x &= 0x000003ff;
                x = (x ^ (x << 16)) & 0xff0000ff;
                x = (x ^ (x << 8)) & 0x0300f00f;
                x = (x ^ (x << 4)) & 0x030c30c3;
                x = (x ^ (x << 2)) & 0x09249249;
                return x;
            };
            return (Part1By2(z) << 2) + (Part1By2(y) << 1) + Part1By2(x);
